import * as fs from "node:fs";

/**
 * The marker banner heading every file the galley-js builders generate.
 * Builders refuse to overwrite a file that lacks it, so a hand-written
 * file in a generated path survives a rebuild (shared contract:
 * "every generated file carries its marker banner").
 */
export const GENERATED_BANNER = "// Generated by galley-js bindings; DO NOT EDIT.";

/**
 * True when `filePath` already exists without {@link GENERATED_BANNER}:
 * a foreign file the builder must not clobber.
 */
export function lacksGeneratedMarker(filePath) {
  return fs.existsSync(filePath) && !fs.readFileSync(filePath, "utf-8").includes(GENERATED_BANNER);
}
